async function handleExportPdf(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  try {
    const type = (url.searchParams.get("type") || "invoice").toLowerCase();
    const factoryId = session.factory_id;
    const yearLabel = session.year_label;

    let pdfBuffer;
    let filename;

    if (type === "invoice") {
      const invNo = url.searchParams.get("no") || url.searchParams.get("invNo") || "";
      const subType = (url.searchParams.get("subType") || url.searchParams.get("invType") || "mfg").toLowerCase();
      pdfBuffer = await generateInvoicePdf(pool, { factoryId, yearLabel, invNo, type: subType });
      filename = `Tax_Invoice_${subType.toUpperCase()}_${invNo || "doc"}.pdf`;
    } else if (type === "dc") {
      const dcNo = url.searchParams.get("no") || url.searchParams.get("dcNo") || "";
      const subType = (url.searchParams.get("subType") || "mfg").toLowerCase();
      pdfBuffer = await generateDcPdf(pool, { factoryId, yearLabel, dcNo, type: subType });
      filename = `Delivery_Challan_${dcNo || "doc"}.pdf`;
    } else if (type === "po") {
      const poId = url.searchParams.get("id") || url.searchParams.get("poId") || "";
      const poNo = url.searchParams.get("no") || url.searchParams.get("poNo") || "";
      pdfBuffer = await generatePoPdf(pool, { factoryId, yearLabel, poId, poNo });
      filename = `Purchase_Order_${poNo || poId || "doc"}.pdf`;
    } else if (type === "salary") {
      const year = url.searchParams.get("year");
      const month = url.searchParams.get("month");
      const staffId = url.searchParams.get("staffId");
      pdfBuffer = await generateSalaryPdf(pool, { factoryId, year, month, staffId });
      filename = `Salary_Slip_${staffId || "staff"}_${month}_${year}.pdf`;
    } else if (type === "traceability") {
      const query = url.searchParams.get("q") || url.searchParams.get("query") || "";
      const dir = url.searchParams.get("dir") || "backward";
      pdfBuffer = await generateTraceabilityPdf(pool, { factoryId, yearLabel, query, dir });
      filename = `EN10204_Traceability_Dossier_${query || "cert"}.pdf`;
    } else {
      return sendJson(res, 400, { error: `Unsupported PDF export type: ${type}` });
    }

    await recordAuditLog(pool, {
      factoryId,
      yearLabel,
      userCode: session.user_code,
      username: session.username,
      action: "EXPORT_PDF",
      module: type.toUpperCase(),
      recordId: filename,
      details: { type, filename, bytes: pdfBuffer.length },
      ipAddress: req.socket ? req.socket.remoteAddress : "127.0.0.1",
      severity: "INFO"
    });

    res.writeHead(200, {
      "Content-Type": "application/pdf",
      "Content-Disposition": `inline; filename="${filename}"`,
      "Content-Length": pdfBuffer.length,
      "Cache-Control": "no-cache"
    });
    res.end(pdfBuffer);
  } catch (err) {
    console.error("handleExportPdf error:", err);
    sendJson(res, 500, { error: err.message || "Failed to generate PDF." });
  }
}

async function handleExportExcel(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  try {
    const type = (url.searchParams.get("type") || "stock").toLowerCase();
    const format = (url.searchParams.get("format") || "xlsx").toLowerCase();
    const factoryId = session.factory_id;
    const yearLabel = session.year_label;

    let exportResult;

    if (type === "stock") {
      const method = url.searchParams.get("method") || "WAC";
      const storeId = url.searchParams.get("storeId");
      const categoryId = url.searchParams.get("categoryId");
      exportResult = await exportStockExcel(pool, { factoryId, yearLabel, method, storeId, categoryId, format });
    } else if (type === "invoices" || type === "sales" || type === "ledger") {
      const fromDate = url.searchParams.get("fromDate");
      const toDate = url.searchParams.get("toDate");
      exportResult = await exportInvoicesExcel(pool, { factoryId, yearLabel, fromDate, toDate, format });
    } else if (type === "payroll" || type === "salary") {
      const year = url.searchParams.get("year");
      const month = url.searchParams.get("month");
      exportResult = await exportPayrollExcel(pool, { factoryId, year, month, format });
    } else if (type === "orderbook" || type === "dc") {
      exportResult = await exportOrderBookExcel(pool, { factoryId, yearLabel, format });
    } else {
      return sendJson(res, 400, { error: `Unsupported Excel export type: ${type}` });
    }

    const contentType = (format === "csv")
      ? "text/csv; charset=utf-8"
      : "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";

    await recordAuditLog(pool, {
      factoryId,
      yearLabel,
      userCode: session.user_code,
      username: session.username,
      action: "EXPORT_EXCEL",
      module: type.toUpperCase(),
      recordId: exportResult.filename,
      details: { type, format, filename: exportResult.filename, bytes: exportResult.buffer.length },
      ipAddress: req.socket ? req.socket.remoteAddress : "127.0.0.1",
      severity: "INFO"
    });

    res.writeHead(200, {
      "Content-Type": contentType,
      "Content-Disposition": `attachment; filename="${exportResult.filename}"`,
      "Content-Length": exportResult.buffer.length,
      "Cache-Control": "no-cache"
    });
    res.end(exportResult.buffer);
  } catch (err) {
    console.error("handleExportExcel error:", err);
    sendJson(res, 500, { error: err.message || "Failed to generate Excel export." });
  }
}

