  if (!rights || rights.mnuUserStatus === 0) return sendJson(res, 403, { ok: false });
  const license = await pool.query(
    "SELECT comp_name FROM licenses WHERE factory_id = $1 AND year_label = $2",
    [session.factory_id, session.year_label]
  );
  const systems = await pool.query(
    `SELECT sys_id, sys_date, sys_name, sys_ip FROM imp_systems
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY sys_id`,
    [session.factory_id, session.year_label]
  );
