async function handleCustomerGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const rights = await customerRights(session);
  if (!rights) return sendJson(res, 403, { ok: false });
  const types = await pool.query(
    `SELECT busi_type, busi_type_name FROM business_type
     WHERE factory_id = $1 AND year_label = $2 AND cust = true
     ORDER BY busi_type_name`,
    [session.factory_id, session.year_label]
  );
  const rows = await pool.query(
    `SELECT * FROM customer WHERE factory_id = $1 AND year_label = $2 ORDER BY cust_id`,
    [session.factory_id, session.year_label]
  );
  const lines = await pool.query(
    `SELECT * FROM customer_indirect WHERE factory_id = $1 AND year_label = $2 ORDER BY cust_id, alt_cust_id`,
    [session.factory_id, session.year_label]
  );
  const byCustomer = new Map();
  for (const line of lines.rows) {
    const list = byCustomer.get(line.cust_id) || [];
    list.push({
      slNo: String(line.alt_cust_id),
      name: String(line.alt_cust_name || "").trim(),
      addr1: String(line.alt_cust_addr1 || "").trim(),
      addr2: String(line.alt_cust_addr2 || "").trim(),
      city: String(line.city || "").trim(),
      country: String(line.country || "").trim(),
      phone: String(line.phmail || "").trim(),
      tin: String(line.vat_reg_no || "").trim(),
      ce: String(line.ce_reg_no || "").trim()
    });
    byCustomer.set(line.cust_id, list);
  }
  const next = await pool.query(
    `SELECT COALESCE(MAX(cust_id), 0) + 1 AS next_id FROM customer WHERE factory_id = $1 AND year_label = $2`,
    [session.factory_id, session.year_label]
  );
  return sendJson(res, 200, {
    title: session.factory_name,
    right: Object.prototype.hasOwnProperty.call(rights, "mnuCustomer") ? rights.mnuCustomer : null,
    nextId: next.rows[0].next_id,
    types: types.rows.map((row) => ({ id: row.busi_type, name: String(row.busi_type_name || "").trim() })),
    customers: rows.rows.map((row) => ({
      id: row.cust_id,
      name: String(row.cust_name || "").trim(),
      addr: String(row.cust_addr || "").trim(),
      kst: String(row.kst_no || "").trim(),
      cst: String(row.cst_no || "").trim(),
      tin: String(row.vat_reg_no || "").trim(),
      vend: String(row.vend_code || "").trim(),
      phone: String(row.phmail || "").trim(),
      email: String(row.email || "").trim(),
      busiType: row.busi_type,
      openBal: row.open_bal,
      openBalPndg: row.open_bal_pndg,
      contact: String(row.contact || "").trim(),
      scope: String(row.scope || "").trim(),
      rng: String(row.rng || "").trim(),
      divi: String(row.divi || "").trim(),
      commission: String(row.commission || "").trim(),
      ce: String(row.ce_reg_no || "").trim(),
      gstin: String(row.gstin || "").trim(),
      stateCode: String(row.state_code || "29").trim(),
      stateName: String(row.state_name || "Karnataka").trim(),
      inactive: row.inactive === true,
      lines: byCustomer.get(row.cust_id) || []
    }))
  });
}

