function itemNumber(value) {
  const number = Number(String(value == null ? "" : value).trim());
  return Number.isFinite(number) ? number : 0;
}

async function itemRights(session) {
  const rights = await loadRights(session);
  if (!rights || rights.mnuItem === 0) return null;
  return rights;
}

function mapItem(row) {
  return {
    id: row.item_id,
    code: String(row.item_code || "").trim(),
    drg: String(row.drg_no || "").trim(),
    name: String(row.item_name || "").trim(),
    detail: String(row.item_detail || "").trim(),
    desn: String(row.item_desn || "").trim(),
    categoryId: row.category_code,
    measure: String(row.measure_unit || "").trim(),
    purchase: String(row.purchase_unit || "").trim(),
    convert: row.unit_convert,
    rate: row.rate,
    rol: String(row.rol || "").trim(),
    rack: String(row.rack_no || "").trim(),
    tariff: String(row.tariff_sub_head || "").trim(),
    hsnCode: String(row.hsn_code || row.tariff_sub_head || "8482").trim(),
    gstRate: row.gst_rate != null ? Number(row.gst_rate) : 18.0,
    cycle: row.cycle_time,
    hide: row.hide === true
  };
}

async function handleItemGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const rights = await itemRights(session);
  if (!rights) return sendJson(res, 403, { ok: false });
  const key = [session.factory_id, session.year_label];
  const categories = await pool.query(
    `SELECT category_code, category_name FROM category
     WHERE factory_id = $1 AND year_label = $2 ORDER BY category_name`,
    key
  );
  const measures = await pool.query(
    `SELECT measure_code, measure_name FROM measurement
     WHERE factory_id = $1 AND year_label = $2 ORDER BY measure_code`,
    key
  );
  const items = await pool.query(
    `SELECT * FROM item WHERE factory_id = $1 AND year_label = $2 ORDER BY item_id`,
    key
  );
  const next = await pool.query(
    `SELECT COALESCE(MAX(item_id), 0) + 1 AS next_id FROM item WHERE factory_id = $1 AND year_label = $2`,
    key
  );
  const focus = await pool.query(
    `SELECT category_code FROM item
     WHERE factory_id = $1 AND year_label = $2
       AND item_id = (SELECT MAX(item_id) FROM item WHERE factory_id = $1 AND year_label = $2)`,
    key
  );
  const tariffs = [];
  for (const row of items.rows) {
    const text = String(row.tariff_sub_head || "").trim();
    if (text && !tariffs.includes(text)) tariffs.push(text);
  }
  tariffs.sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
  return sendJson(res, 200, {
    title: session.factory_name,
    right: Object.prototype.hasOwnProperty.call(rights, "mnuItem") ? rights.mnuItem : null,
    nextId: next.rows[0].next_id,
    focusCategoryId: focus.rowCount ? focus.rows[0].category_code : null,
    categories: categories.rows.map((row) => ({
      id: row.category_code,
      name: String(row.category_name || "").trim()
    })),
    measures: measures.rows.map((row) => ({
      code: row.measure_code,
      name: String(row.measure_name || "").trim()
    })),
    tariffs,
    items: items.rows.map(mapItem)
  });
}

async function itemCategoryGuard(session, itemId, categoryId) {
  const locks = [
    [1, "comp_master", "rm_id", "You should not change the Category... It should be 'Raw Material' Only,\r\nSince 'Component Master' screen uses this Item as a 'Raw Material'"],
    [2, "comp_master", "item_id", "You should not change the Category... It should be 'Component' Only,\r\nSince 'Component Master' screen uses this Item as a 'Component'"],
    [3, "assmbly_def", "assmbly_id", "You should not change the Category... It should be 'Assembly' Only,\r\nSince 'Bill of Material' screen uses this Item as a 'Assembly'"],
    [7, "assmbly_def", "assmbly_id", "You should not change the Category... It should be 'Sub-Assembly' Only,\r\nSince 'Bill of Material' screen uses this Item as a 'Sub-Assembly'"]
  ];
  for (const [code, table, column, message] of locks) {
    if (Number(categoryId) === code) continue;
    if (await machineUsed(session, table, column, itemId)) return message;
  }
  return "";
}

async function handleItemSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const rights = await itemRights(session);
  if (!rights) return sendJson(res, 403, { ok: false });
  const body = await readBody(req);
  const mode = body.mode === "edit" ? "edit" : "new";
  const level = rightsByte(Object.prototype.hasOwnProperty.call(rights, "mnuItem") ? rights.mnuItem : null);
  if (!allowsUserWrite(level, mode)) return sendJson(res, 403, { ok: false });
  const code = String(body.code == null ? "" : body.code).trim();
  const name = String(body.name == null ? "" : body.name).trim();
  if (!code) return sendJson(res, 200, { ok: false, message: "Enter the Item Code/Part No. / Drg. No....." });
  if (!name) return sendJson(res, 200, { ok: false, message: "Enter the Item Name....." });
  const categoryId = Number(body.categoryId);
  if (!Number.isInteger(categoryId) || categoryId < 1) {
    return sendJson(res, 200, { ok: false, message: "Enter the Category code....." });
  }
  const measure = String(body.measure == null ? "" : body.measure).trim();
  const purchase = String(body.purchase == null ? "" : body.purchase).trim();
  if (!measure) return sendJson(res, 200, { ok: false, message: "Enter the Unit of Measurement (for Stock Purpose)....." });
  if (!purchase) return sendJson(res, 200, { ok: false, message: "Enter the Ordering Unit (for Purchase)....." });
  const typedConvert = itemNumber(body.convert);
  if (typedConvert === 0) {
    return sendJson(res, 200, {
      ok: false,
      message: "Enter the Conversion factor between 'Unit of Measurement (for Stock Purpose)' and 'Ordering Unit (for Purchase)'....."
    });
  }
  let id = Number(body.id);
  if (!Number.isInteger(id) || id < 1) id = 0;
  if (mode === "edit") {
    const locked = await itemCategoryGuard(session, id, categoryId);
    if (locked) return sendJson(res, 200, { ok: false, message: locked });
  }
  if (mode === "new") {
    const taken = id
      ? await pool.query(
        "SELECT 1 FROM item WHERE factory_id = $1 AND year_label = $2 AND item_id = $3",
        [session.factory_id, session.year_label, id]
      )
      : { rowCount: 1 };
    if (taken.rowCount) {
      const next = await pool.query(
        `SELECT COALESCE(MAX(item_id), 0) + 1 AS next_id FROM item WHERE factory_id = $1 AND year_label = $2`,
        [session.factory_id, session.year_label]
      );
      id = next.rows[0].next_id;
    }
  }
  const duplicate = await pool.query(
    `SELECT 1 FROM item
     WHERE factory_id = $1 AND year_label = $2
       AND lower(btrim(item_code)) = lower(btrim($3))
       AND item_id <> $4
     LIMIT 1`,
    [session.factory_id, session.year_label, code, id]
  );
  if (duplicate.rowCount) {
    return sendJson(res, 200, { ok: false, message: "An Entry Already Exists...Try Another!" });
  }
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true });
  const convert = measure.toUpperCase() === purchase.toUpperCase() ? 1 : typedConvert;
  const hsnCode = machineText(body.hsnCode || body.tariff || "8482");
  const gstRate = body.gstRate != null ? Number(body.gstRate) : 18.0;
  const values = [
    session.factory_id, session.year_label, id, code, name, categoryId, measure, purchase,
    convert, itemNumber(body.rate), machineText(body.rol), machineText(body.rack),
    machineText(body.tariff), itemNumber(body.cycle), body.hide === true,
    machineText(body.detail), machineText(body.desn), machineText(body.drg),
    hsnCode, gstRate
  ];
  if (mode === "new") {
    await pool.query(
      `INSERT INTO item (
         factory_id, year_label, item_id, item_code, item_name, category_code,
         measure_unit, purchase_unit, unit_convert, rate, rol, rack_no, tariff_sub_head, cycle_time, hide,
         item_detail, item_desn, drg_no, hsn_code, gst_rate
       ) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::double precision,$10::double precision,$11,$12,$13,$14::double precision,$15,$16,$17,$18,$19,$20::double precision)`,
      values
    );
  } else {
    await pool.query(
      `UPDATE item SET item_code = $4, item_name = $5, category_code = $6, measure_unit = $7,
         purchase_unit = $8, unit_convert = $9::double precision, rate = $10::double precision,
         rol = $11, rack_no = $12, tariff_sub_head = $13, cycle_time = $14::double precision, hide = $15,
         item_detail = $16, item_desn = $17, drg_no = $18, hsn_code = $19, gst_rate = $20::double precision
       WHERE factory_id = $1 AND year_label = $2 AND item_id = $3`,
      values
    );
  }
  const message = mode === "edit" ? "Records Modified!" : "Records Saved!";
  return sendJson(res, 200, { ok: true, message, id });
}

