async function handleStoreSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const rights = await storeRights(session);
  if (!rights) return sendJson(res, 403, { ok: false });
  const body = await readBody(req);
  const mode = body.mode === "edit" ? "edit" : "new";
  const level = rightsByte(Object.prototype.hasOwnProperty.call(rights, "mnuStores") ? rights.mnuStores : null);
  if (!allowsUserWrite(level, mode)) return sendJson(res, 403, { ok: false });
  const name = String(body.name == null ? "" : body.name).trim();
  if (!name) return sendJson(res, 200, { ok: false, message: "Please Enter the Store Name....." });
  if (body.addable !== true && body.issuable !== true) {
    return sendJson(res, 200, {
      ok: false,
      message: "You should enable this store atleast for 'Addable' or 'Issuable'....."
    });
  }
  let id = Number(body.id);
  if (!Number.isInteger(id) || id < 1) id = 0;
  if (mode === "new") {
    const taken = id
      ? await pool.query(
        "SELECT 1 FROM store WHERE factory_id = $1 AND year_label = $2 AND store_id = $3",
        [session.factory_id, session.year_label, id]
      )
      : { rowCount: 1 };
    if (taken.rowCount) {
      const next = await pool.query(
        `SELECT COALESCE(MAX(store_id), 0) + 1 AS next_id FROM store WHERE factory_id = $1 AND year_label = $2`,
        [session.factory_id, session.year_label]
      );
      id = next.rows[0].next_id;
    }
  }
  if (await storeDuplicate(session, name, id)) {
    return sendJson(res, 200, { ok: false, message: "An Entry Already Exists...Try Another!" });
  }
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true });
  const desc = machineText(body.desc);
  if (mode === "new") {
    await pool.query(
      `INSERT INTO store (factory_id, year_label, store_id, store_name, can_add, can_issue, store_desc)
       VALUES ($1,$2,$3,$4,$5,$6,$7)`,
      [session.factory_id, session.year_label, id, name, body.addable === true, body.issuable === true, desc]
    );
  } else {
    await pool.query(
      `UPDATE store SET store_name = $4, can_add = $5, can_issue = $6, store_desc = $7
       WHERE factory_id = $1 AND year_label = $2 AND store_id = $3`,
      [session.factory_id, session.year_label, id, name, body.addable === true, body.issuable === true, desc]
    );
  }
  return sendJson(res, 200, { ok: true, message: mode === "edit" ? "Records Modified!" : "Records Saved!", id });
}

