async function handleCurrTodaySave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const rights = masterRight(await loadRights(session), "mnuCurrToday");
  if (!rights) return sendJson(res, 403, { ok: false });
  const body = await readBody(req);
  const level = rightsByte(Object.prototype.hasOwnProperty.call(rights, "mnuCurrToday") ? rights.mnuCurrToday : null);
  if (level === 0 || level === 1) return sendJson(res, 403, { ok: false });
  const currId = Number(body.currId);
  const rate = Number(body.rate);
  const previous = await pool.query(
    `SELECT curr_value_in_rs FROM currency_today
     WHERE factory_id = $1 AND year_label = $2 AND curr_id = $3 AND curr_value_date < CURRENT_DATE
     ORDER BY id DESC LIMIT 1`,
    [session.factory_id, session.year_label, currId]
  );
  const previousRate = previous.rowCount ? Number(previous.rows[0].curr_value_in_rs) : 0;
  if (Number.isFinite(rate) && rate === previousRate) {
    return sendJson(res, 200, { ok: false, message: "No need to save this Record, since the Previous Rate and today's Rate are same!!!" });
  }
  if (!Number.isInteger(currId) || currId < 1) {
    return sendJson(res, 200, { ok: false, message: "Please Select the CurrencyName....." });
  }
  if (!Number.isFinite(rate) || rate === 0) {
    return sendJson(res, 200, { ok: false, message: "Invalid Currency Value....." });
  }
  const saving = body.mode !== "modify";
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true, confirm: saving ? "Are You Sure To Save  ?" : "Are You Sure To Modify  ?" });
  await pool.query(
    "DELETE FROM currency_today WHERE factory_id = $1 AND year_label = $2 AND curr_id = $3 AND curr_value_date = CURRENT_DATE",
    [session.factory_id, session.year_label, currId]
  );
  const next = await pool.query(
    "SELECT COALESCE(MAX(id), 0) + 1 AS next_id FROM currency_today WHERE factory_id = $1 AND year_label = $2",
    [session.factory_id, session.year_label]
  );
  const picked = String(body.date || "").slice(0, 10);
  await pool.query(
    `INSERT INTO currency_today (factory_id, year_label, id, curr_id, curr_value_in_rs, curr_value_date)
     VALUES ($1,$2,$3,$4,$5::double precision, COALESCE($6::date, CURRENT_DATE))`,
    [session.factory_id, session.year_label, next.rows[0].next_id, currId, rate, picked || null]
  );
  return sendJson(res, 200, { ok: true, message: saving ? "Record Saved" : "Record Modified" });
}

