function gridRows(body) {
  return Array.isArray(body.rows) ? body.rows : [];
}

function slnoOf(row) {
  const number = Number(String(row.slno == null ? "" : row.slno).trim());
  return Number.isFinite(number) ? Math.trunc(number) : 0;
}

function uniqueSlno(rows) {
  const seen = new Set();
  for (const row of rows) {
    const slno = slnoOf(row);
    if (seen.has(slno)) return false;
    seen.add(slno);
  }
  return true;
}

function stoppageError(rows) {
  const names = [];
  for (let i = 0; i < rows.length; i += 1) {
    const name = String(rows[i].type == null ? "" : rows[i].type).trim();
    for (let j = i + 1; j < rows.length; j += 1) {
      if (name === String(rows[j].type == null ? "" : rows[j].type).trim()) {
        return "Duplication of  Production DownTime Type Not Allowed !!!";
      }
    }
    names.push(name);
  }
  if (!rows.length) return "Please Enter the  details by clicking the grid heading...";
  for (const row of rows) {
    const name = String(row.type == null ? "" : row.type).trim();
    if (!name) return "Enter a Valid  Production DownTime Type  for the SlNo." + String(row.slno == null ? "" : row.slno);
  }
  return "";
}

function groupingError(rows, names) {
  for (let i = 0; i < rows.length; i += 1) {
    const name = String(rows[i].name == null ? "" : rows[i].name).trim();
    for (let j = i + 1; j < rows.length; j += 1) {
      if (name === String(rows[j].name == null ? "" : rows[j].name).trim()) {
        return "Duplication of  Employee names Not Allowed !!!";
      }
    }
  }
  if (!rows.length) return "Please Enter the  details by clicking the grid heading...";
  const known = new Set(names);
  for (const row of rows) {
    const name = String(row.name == null ? "" : row.name).trim();
    const slno = String(row.slno == null ? "" : row.slno);
    if (!name) return "Enter a Valid  Employee Name  for the SlNo." + slno;
    if (!known.has(name)) return "Employee Name  Not Exists...for the SlNo." + slno;
  }
  return "";
}

async function handleProdSetupGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const stops = await pool.query(
    "SELECT slno, prod_stop_type, efficiency_perc FROM prod_eff_constraints WHERE factory_id = $1 AND year_label = $2 ORDER BY slno",
    [session.factory_id, session.year_label]
  );
  const daily = await pool.query(
    "SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'dailyprod' AND column_name = 'staff'"
  );
  const heads = await pool.query(
    daily.rowCount
      ? `SELECT staff_id, staff_name FROM staff
         WHERE factory_id = $1 AND year_label = $2 AND status_c IS TRUE
         AND staff_id NOT IN (SELECT staff FROM dailyprod)
         ORDER BY staff_name`
      : `SELECT staff_id, staff_name FROM staff
         WHERE factory_id = $1 AND year_label = $2 AND status_c IS TRUE
         ORDER BY staff_name`,
    [session.factory_id, session.year_label]
  );
  const everyone = await pool.query(
    "SELECT staff_id, staff_name FROM staff WHERE factory_id = $1 AND year_label = $2 ORDER BY staff_name",
    [session.factory_id, session.year_label]
  );
  sendJson(res, 200, {
    title: "Master - My Company Details - Production",
    stoppages: stops.rows.map((row) => ({
      slno: row.slno,
      type: row.prod_stop_type || "",
      perc: row.efficiency_perc == null ? "" : String(row.efficiency_perc)
    })),
    heads: heads.rows.map((row) => ({ id: row.staff_id, name: row.staff_name || "" })),
    staff: everyone.rows.map((row) => ({ id: row.staff_id, name: row.staff_name || "" }))
  });
}

async function handleProdStopSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in again." });
  const body = await readBody(req);
  const rows = gridRows(body);
  const message = stoppageError(rows);
  if (message) return sendJson(res, 200, { ok: false, message });
  if (!uniqueSlno(rows)) return sendJson(res, 200, { ok: false });
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true });
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("DELETE FROM prod_eff_constraints WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label]);
    for (const row of rows) {
      await client.query(
        `INSERT INTO prod_eff_constraints (factory_id, year_label, slno, prod_stop_type, efficiency_perc)
         VALUES ($1, $2, $3, $4, $5)`,
        [session.factory_id, session.year_label, slnoOf(row), String(row.type).trim(), machineRate(row.perc)]
      );
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
  sendJson(res, 200, { ok: true, message: "Record Stored ." });
}

