async function handleCompanyEouSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const emptying = eouEmpty(body);
  if (!emptying && !String(body.licNo || "").trim()) {
    return sendJson(res, 200, { ok: false, message: "Without the License No. you cannot store this EOU details..... " });
  }
  if (!emptying && String(body.licUpto || "") < String(body.licDate || "")) {
    return sendJson(res, 200, { ok: false, message: "License 'Valid Upto' date should not be lesser than License 'dated' ..... " });
  }
  if (!emptying && !String(body.person || "").trim() && String(body.contact || "").trim()) {
    return sendJson(res, 200, { ok: false, message: "'Authorised Person' should not be empty in order to enter the 'Contact No.'" });
  }
  const caption = body.caption === "Modify" ? "Modify" : "Save";
  if (body.confirmed !== true) {
    return sendJson(res, 200, {
      ok: true,
      ready: true,
      confirm: emptying ? "Are you sure to Delete / Empty the EOU Details !!!" : "Are You Sure To " + caption + "?"
    });
  }
  const lic = blankNull(body.licNo);
  const formType = blankNull(body.formType);
  const note = blankNull(body.noteNo);
  await pool.query(
    `UPDATE misc SET
      eou_lic_no = $3, eou_lic_date = $4, eou_lic_upto = $5,
      eou_form_type = $6, eou_bond_no = $7, eou_form_date = $8, eou_bond_amt = $9,
      notification_no = $10, notification_date = $11,
      authorised_sign = $12, authorised_contact = $13, eou_remarks = $14
     WHERE factory_id = $1 AND year_label = $2`,
    [
      session.factory_id, session.year_label,
      lic, lic ? body.licDate : null, lic ? body.licUpto : null,
      formType, formType ? blankNull(body.bondNo) : null, formType ? body.formDate : null,
      formType ? machineRate(body.bondAmt) : 0,
      note, note ? body.noteDate : null,
      blankNull(body.person), blankNull(body.contact), blankNull(body.remarks)
    ]
  );
  if (emptying) return sendJson(res, 200, { ok: true, message: "EOU Details Deleted....", caption });
  return sendJson(res, 200, {
    ok: true,
    message: caption === "Save" ? "Records Saved..." : "Records Modified...",
    caption: "Modify"
  });
}

