async function restoreIssue(client, session, issueId) {
  const lines = await client.query(
    "SELECT item_id, trak FROM store_iss_sub WHERE factory_id = $1 AND year_label = $2 AND id = $3",
    [session.factory_id, session.year_label, issueId]
  );
  for (const line of lines.rows) {
    const parts = String(line.trak || "").split(",");
    for (let index = 0; index < parts.length - 1; index += 2) {
      const receiptId = Number(parts[index]);
      const qty = Number(parts[index + 1]);
      if (!receiptId || !(qty > 0)) continue;
      const current = await client.query(
        "SELECT trak FROM store_add_sub WHERE factory_id = $1 AND year_label = $2 AND id = $3 AND item_id = $4",
        [session.factory_id, session.year_label, receiptId, line.item_id]
      );
      let trak = current.rowCount ? String(current.rows[0].trak || "") : "";
      const piece = issueId + "," + qty;
      if (trak === piece) trak = "";
      else if (trak.endsWith("," + piece)) trak = trak.slice(0, -(piece.length + 1));
      await client.query(
        "UPDATE store_add_sub SET bal_qty = bal_qty + $4, trak = $5 WHERE factory_id = $1 AND year_label = $2 AND id = $3 AND item_id = $6",
        [session.factory_id, session.year_label, receiptId, qty, trak, line.item_id]
      );
    }
  }
  await client.query("DELETE FROM store_iss_sub WHERE factory_id = $1 AND year_label = $2 AND id = $3", [session.factory_id, session.year_label, issueId]);
  await client.query("DELETE FROM store_iss WHERE factory_id = $1 AND year_label = $2 AND id = $3", [session.factory_id, session.year_label, issueId]);
}

async function handleScnGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const [addStores, sourceStores, costs, pending, saved, subs] = await Promise.all([
    pool.query("SELECT store_id, store_name FROM store WHERE factory_id = $1 AND year_label = $2 AND can_add = true ORDER BY store_name", [session.factory_id, session.year_label]),
    pool.query("SELECT store_id, store_name FROM store WHERE factory_id = $1 AND year_label = $2 ORDER BY store_name", [session.factory_id, session.year_label]),
    pool.query("SELECT id, cost_cntr FROM cost_center WHERE factory_id = $1 AND year_label = $2 ORDER BY cost_cntr", [session.factory_id, session.year_label]),
    pool.query("SELECT dc_id, dc_no, dc_date, ref_dc_no, ref_dc_date, store_id, cost_cntr_id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2 AND COALESCE(scn_prod_id, 0) = 0 ORDER BY dc_id", [session.factory_id, session.year_label]),
    pool.query("SELECT * FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2 AND COALESCE(scn_prod_id, 0) > 0 ORDER BY scn_prod_id", [session.factory_id, session.year_label]),
    pool.query(
      `SELECT s.*, i.item_code, i.item_name, i.measure_unit
       FROM prodn_iwo_ret_sub s
       LEFT JOIN item i ON i.factory_id = s.factory_id AND i.year_label = s.year_label AND i.item_id = s.item_id
       WHERE s.factory_id = $1 AND s.year_label = $2 ORDER BY s.dc_id, s.slno`,
      [session.factory_id, session.year_label]
    )
  ]);
  const [issues, adds] = await Promise.all([
    pool.query("SELECT id, store_id FROM store_iss WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label]),
    pool.query("SELECT id, store_id FROM store_add WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label])
  ]);
  const issueStore = new Map(issues.rows.map((row) => [Number(row.id), row.store_id]));
  const addStore = new Map(adds.rows.map((row) => [Number(row.id), row.store_id]));
  const stock = await pool.query(
    `SELECT a.store_id, s.item_id, COALESCE(SUM(s.bal_qty), 0) AS qty
     FROM store_add_sub s
     JOIN store_add a ON a.factory_id = s.factory_id AND a.year_label = s.year_label AND a.id = s.id
     WHERE s.factory_id = $1 AND s.year_label = $2
     GROUP BY a.store_id, s.item_id`,
    [session.factory_id, session.year_label]
  );
  const lines = {};
  subs.rows.forEach((row) => {
    const key = String(row.dc_id);
    if (!lines[key]) lines[key] = [];
    lines[key].push({
      slno: row.slno,
      itemId: row.item_id,
      code: row.item_code || "",
      name: row.item_name || "",
      uom: row.measure_unit || "",
      received: Number(row.qty) || 0,
      accepted: Number(row.accp_qty) || 0,
      rejected: Number(row.rej_qty) || 0,
      remarks: row.rej_row_rem === " " ? "" : (row.rej_row_rem || "")
    });
  });
  const nextRow = await pool.query(
    "SELECT COALESCE(MAX(scn_prod_id), 0) + 1 AS id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2",
    [session.factory_id, session.year_label]
  );
  return sendJson(res, 200, {
    addStores: addStores.rows,
    sourceStores: sourceStores.rows,
    costs: costs.rows,
    stock: stock.rows.map((row) => ({ storeId: row.store_id, itemId: row.item_id, qty: Number(row.qty) })),
    pending: pending.rows.map((row) => ({
      id: row.dc_id,
      no: row.dc_no,
      date: dateText(row.dc_date),
      refNo: row.ref_dc_no || "",
      refDate: dateText(row.ref_dc_date),
      storeId: row.store_id,
      costId: row.cost_cntr_id || 0,
      lines: lines[String(row.dc_id)] || []
    })),
    nextNo: String(nextRow.rows[0].id),
    records: saved.rows.map((row) => ({
      id: row.dc_id,
      scnId: row.scn_prod_id,
      date: dateText(row.scn_prod_date),
      returnNo: row.dc_no,
      returnDate: dateText(row.dc_date),
      refNo: row.ref_dc_no || "",
      refDate: dateText(row.ref_dc_date),
      sourceId: issueStore.get(Number(row.store_iss_id)) || row.store_id || 0,
      destId: addStore.get(Number(row.store_add_id)) || 0,
      costId: row.cost_cntr_id || 0,
      prepared: row.prep_by === " " ? "" : (row.prep_by || ""),
      remarks: row.rem_any === " " ? "" : (row.rem_any || ""),
      lines: lines[String(row.dc_id)] || []
    }))
  });
}

async function handleScnSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const dcId = Number(body.returnId);
  const note = await pool.query(
    "SELECT dc_id, scn_prod_id, store_iss_id, store_add_id, tmp_store_add_id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3",
    [session.factory_id, session.year_label, dcId]
  );
  if (!note.rowCount) return sendJson(res, 200, { ok: false, message: "Not a Valid Produced Matl. Return  Number..." });
  const sourceId = Number(body.sourceId);
  const destId = Number(body.destId);
  const source = await pool.query("SELECT store_id FROM store WHERE factory_id = $1 AND year_label = $2 AND store_id = $3", [session.factory_id, session.year_label, sourceId]);
  if (!source.rowCount) return sendJson(res, 200, { ok: false, message: "Please Select a Store from which the Stock is to be Reduced" });
  const dest = await pool.query("SELECT store_id FROM store WHERE factory_id = $1 AND year_label = $2 AND store_id = $3 AND can_add = true", [session.factory_id, session.year_label, destId]);
  if (!dest.rowCount) return sendJson(res, 200, { ok: false, message: "Please Select a Store to which the stock is to be Added" });
  if (sourceId === destId) return sendJson(res, 200, { ok: false, message: "Both Stores should not be the same ... " });
  const lines = Array.isArray(body.lines) ? body.lines : [];
  if (!lines.length) return sendJson(res, 200, { ok: false, message: "Please Enter the ItemName/Item details by clicking the grid heading..." });
  const prepared = [];
  for (const line of lines) {
    const accepted = Number(line.accepted) || 0;
    const rejected = Number(line.rejected) || 0;
    if (accepted + rejected === 0) return sendJson(res, 200, { ok: false, message: "Both Accepted Qty and Rejected Qty should not be Zero... " });
    const item = await pool.query(
      `SELECT s.item_id, COALESCE(i.rate, 0) AS rate
       FROM prodn_iwo_ret_sub s
       LEFT JOIN item i ON i.factory_id = s.factory_id AND i.year_label = s.year_label AND i.item_id = s.item_id
       WHERE s.factory_id = $1 AND s.year_label = $2 AND s.dc_id = $3 AND s.slno = $4`,
      [session.factory_id, session.year_label, dcId, Number(line.slno)]
    );
    if (!item.rowCount) return sendJson(res, 200, { ok: false, message: "Please Enter the ItemName/Item details by clicking the grid heading..." });
    prepared.push({
      slno: Number(line.slno),
      itemId: item.rows[0].item_id,
      rate: Number(item.rows[0].rate) || 0,
      accepted,
      rejected,
      toStock: accepted,
      remarks: machineText(line.remarks).trim() || " "
    });
  }
  if (body.mode === "modify") {
    const blocked = await pool.query(
      `SELECT 1 FROM store_add_sub WHERE factory_id = $1 AND year_label = $2 AND bal_qty <> qty
       AND id = (SELECT store_add_id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3) LIMIT 1`,
      [session.factory_id, session.year_label, dcId]
    );
    if (blocked.rowCount) {
      return sendJson(res, 200, { ok: false, message: "Modification is not Allowed, Since Some material has been issued  from this Store Credit Note" });
    }
  }
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true, confirm: body.mode === "modify" ? "Are You Sure To Modify?" : "Are You Sure To Save?" });
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const costId = Number(body.costId) || 0;
    const preparedBy = machineText(body.prepared).trim() || " ";
    const remarks = machineText(body.remarks).trim() || " ";
    let scnId = Number(note.rows[0].scn_prod_id) || 0;
    if (!scnId) {
      const next = await client.query("SELECT COALESCE(MAX(scn_prod_id), 0) + 1 AS id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label]);
      scnId = Number(next.rows[0].id);
    }
    await client.query(
      `UPDATE prodn_iwo_ret SET scn_prod_id = $4, scn_prod_date = $5, prep_by = $6, rem_any = $7
       WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3`,
      [session.factory_id, session.year_label, dcId, scnId, body.date || null, preparedBy, remarks]
    );
    for (const line of prepared) {
      await client.query(
        `UPDATE prodn_iwo_ret_sub SET accp_qty = $5, rej_qty = $6, rej_row_rem = $7
         WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3 AND slno = $4`,
        [session.factory_id, session.year_label, dcId, line.slno, line.accepted, line.rejected, line.remarks]
      );
    }
    const already = Number(note.rows[0].store_iss_id) || 0;
    if (body.mode !== "modify" && !already) {
      const issueNext = await client.query("SELECT COALESCE(MAX(id), 0) + 1 AS id FROM store_iss WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label]);
      const issueId = Number(issueNext.rows[0].id);
      await client.query(
        `INSERT INTO store_iss (factory_id, year_label, id, doi, ti, cost_cntr_id, store_id, to_whom, rem_any)
         VALUES ($1,$2,$3,$4,'',$5,$6,$7,$8)`,
        [session.factory_id, session.year_label, issueId, body.date || null, costId, sourceId, preparedBy, remarks]
      );
      const addNext = await client.query("SELECT COALESCE(MAX(id), 0) + 1 AS id FROM store_add WHERE factory_id = $1 AND year_label = $2", [session.factory_id, session.year_label]);
      const addId = Number(addNext.rows[0].id);
      await client.query(
        `INSERT INTO store_add (factory_id, year_label, id, store_id, doa, ts, cost_cntr_id, prep_by, rem_any)
         VALUES ($1,$2,$3,$4,$5,'',$6,$7,$8)`,
        [session.factory_id, session.year_label, addId, destId, body.date || null, costId, preparedBy, remarks]
      );
      for (const line of prepared) {
        await issueFromReturnReceipt(client, session, issueId, Number(note.rows[0].tmp_store_add_id) || 0, line.itemId, line.accepted + line.rejected, line.slno);
        await client.query(
          `INSERT INTO store_add_sub (factory_id, year_label, id, item_id, slno, qty, bal_qty, rate, trak)
           VALUES ($1,$2,$3,$4,$5,$6,$6,$7,'')`,
          [session.factory_id, session.year_label, addId, line.itemId, line.slno, line.toStock, line.rate]
        );
      }
      await client.query(
        "UPDATE prodn_iwo_ret SET store_iss_id = $4, store_add_id = $5 WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3",
        [session.factory_id, session.year_label, dcId, issueId, addId]
      );
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  return sendJson(res, 200, { ok: true, message: body.mode === "modify" ? "Record Modified." : "Record Saved" });
}

async function handleScnDelete(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const note = await pool.query(
    "SELECT store_add_id, store_iss_id FROM prodn_iwo_ret WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3",
    [session.factory_id, session.year_label, Number(body.id)]
  );
  if (!note.rowCount) return sendJson(res, 200, { ok: false, message: "Not a Valid Produced Matl. Return  Number..." });
  const addId = Number(note.rows[0].store_add_id) || 0;
  if (addId) {
    const used = await pool.query(
      "SELECT 1 FROM store_add_sub WHERE factory_id = $1 AND year_label = $2 AND id = $3 AND bal_qty <> qty LIMIT 1",
      [session.factory_id, session.year_label, addId]
    );
    if (used.rowCount) {
      return sendJson(res, 200, { ok: false, message: "Deletion is not Allowed, Since Some material has been issued  from this Store Credit Note" });
    }
  }
  if (body.confirmed !== true) return sendJson(res, 200, { ok: true, ready: true, confirm: "Are You Sure To Delete" });
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const issueId = Number(note.rows[0].store_iss_id) || 0;
    if (issueId) await restoreIssue(client, session, issueId);
    if (addId) {
      await client.query("DELETE FROM store_add_sub WHERE factory_id = $1 AND year_label = $2 AND id = $3", [session.factory_id, session.year_label, addId]);
      await client.query("DELETE FROM store_add WHERE factory_id = $1 AND year_label = $2 AND id = $3", [session.factory_id, session.year_label, addId]);
    }
    await client.query(
      "UPDATE prodn_iwo_ret_sub SET accp_qty = 0, rej_qty = 0, rej_row_rem = ' ' WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3",
      [session.factory_id, session.year_label, Number(body.id)]
    );
    await client.query(
      "UPDATE prodn_iwo_ret SET scn_prod_id = 0, prep_by = ' ', rem_any = ' ', store_iss_id = 0, store_add_id = 0 WHERE factory_id = $1 AND year_label = $2 AND dc_id = $3",
      [session.factory_id, session.year_label, Number(body.id)]
    );
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }

  return sendJson(res, 200, { ok: true, message: "Record Deleted Successfully." });
}

async function handlePlanGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const factory = session.factory_id;
  const year = session.year_label;
  const machines = await pool.query(
    `SELECT mach_id, mach_name FROM machine
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY mach_id`,
    [factory, year]
  );
  const items = await pool.query(
    `SELECT item_id, item_code FROM item
     WHERE factory_id = $1 AND year_label = $2 AND COALESCE(hide, false) = false
     ORDER BY item_code`,
    [factory, year]
  );
  const planYear = Number(new URL(req.url, "http://localhost").searchParams.get("year"));
  const machId = Number(new URL(req.url, "http://localhost").searchParams.get("mach"));
  let planData = "";
  let legend = [];
  if (planYear && machId) {
    const saved = await pool.query(
      `SELECT plan_data FROM plan_chart
       WHERE factory_id = $1 AND year_label = $2 AND plan_year = $3 AND mach_id = $4`,
      [factory, year, planYear, machId]
    );
    planData = saved.rows[0] ? saved.rows[0].plan_data || "" : "";
    const rows = await pool.query(
      `SELECT l.sl_no, l.item_id, l.col_code, i.item_code
       FROM itm_legend l
       LEFT JOIN item i
         ON i.factory_id = l.factory_id AND i.year_label = l.year_label AND i.item_id = l.item_id
       WHERE l.factory_id = $1 AND l.year_label = $2 AND l.plan_year = $3 AND l.mach_id = $4
       ORDER BY l.sl_no`,
      [factory, year, planYear, machId]
    );
    legend = rows.rows.map((row) => ({
      slno: row.sl_no,
      itemId: row.item_id,
      code: row.item_code || String(row.item_id),
      color: row.col_code
    }));
  }
  sendJson(res, 200, {
    machines: machines.rows.map((row) => ({ id: row.mach_id, name: row.mach_name || "" })),
    items: items.rows.map((row) => ({ id: row.item_id, code: row.item_code || "" })),
    planData,
    legend
  });
}

async function handlePlanSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const factory = session.factory_id;
  const year = session.year_label;
  const planYear = Number(body.year);
  const machId = Number(body.machId);
  const legend = Array.isArray(body.legend) ? body.legend : [];
  const planData = typeof body.planData === "string" ? body.planData : "";
  if (!Number.isInteger(planYear) || planYear < 1980 || planYear > 2030 || !Number.isInteger(machId) || machId <= 0) {
    return sendJson(res, 400, { error: "Save not allowed. You have not planned Anything" });
  }
  const machine = await pool.query(
    `SELECT mach_id FROM machine WHERE factory_id = $1 AND year_label = $2 AND mach_id = $3`,
    [factory, year, machId]
  );
  if (machine.rowCount === 0 || legend.length === 0) {
    return sendJson(res, 400, { error: "Save not allowed. You have not planned Anything" });
  }
  for (const row of legend) {
    const item = await pool.query(
      `SELECT item_id FROM item WHERE factory_id = $1 AND year_label = $2 AND item_id = $3`,
      [factory, year, Number(row.itemId)]
    );
    if (item.rowCount === 0) {
      return sendJson(res, 400, { error: "Item Does not exist" });
    }
  }
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO plan_chart (factory_id, year_label, plan_year, mach_id, plan_data)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (factory_id, year_label, plan_year, mach_id)
       DO UPDATE SET plan_data = EXCLUDED.plan_data`,
      [factory, year, planYear, machId, planData]
    );
    await client.query(
      `DELETE FROM itm_legend
       WHERE factory_id = $1 AND year_label = $2 AND plan_year = $3 AND mach_id = $4`,
      [factory, year, planYear, machId]
    );
    let slno = 0;
    for (const row of legend) {
      slno += 1;
      await client.query(
        `INSERT INTO itm_legend
           (factory_id, year_label, plan_year, mach_id, sl_no, item_id, col_code)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [factory, year, planYear, machId, slno, Number(row.itemId), Number(row.color) || 0]
      );
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
  sendJson(res, 200, { ok: true });
}

async function handleCapaGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const factory = session.factory_id;
  const year = session.year_label;
  const url = new URL(req.url, "http://127.0.0.1");
  const asked = Number(url.searchParams.get("planId") || 0);
  const ids = await pool.query(
    `SELECT plan_id FROM plan_prod_capa
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY plan_id`,
    [factory, year]
  );
  const items = await pool.query(
    `SELECT item_code FROM item
     WHERE factory_id = $1 AND year_label = $2 AND COALESCE(hide, false) = false
     ORDER BY item_code`,
    [factory, year]
  );
  const processes = await pool.query(
    `SELECT proc_name FROM process_id
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY proc_name`,
    [factory, year]
  );
  const max = await pool.query(
    `SELECT COALESCE(MAX(plan_id), 0) AS n FROM plan_prod_capa
     WHERE factory_id = $1 AND year_label = $2`,
    [factory, year]
  );
  let plan = null;
  if (asked > 0) {
    const found = await pool.query(
      `SELECT plan_id, flex_rows, details FROM plan_prod_capa
       WHERE factory_id = $1 AND year_label = $2 AND plan_id = $3`,
      [factory, year, asked]
    );
    plan = found.rows[0] || null;
  }
  sendJson(res, 200, {
    ids: ids.rows.map((row) => Number(row.plan_id)),
    nextId: Number(max.rows[0].n) + 1,
    items: items.rows.map((row) => row.item_code),
    processes: processes.rows.map((row) => row.proc_name),
    plan: plan ? {
      planId: Number(plan.plan_id),
      flexRows: Number(plan.flex_rows) || 2,
      details: plan.details || ""
    } : null
  });
}

async function handleCapaSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const factory = session.factory_id;
  const year = session.year_label;
  const planId = Number(body.planId);
  const details = typeof body.details === "string" ? body.details : "";
  const flexRows = Number(body.flexRows);
  if (!Number.isInteger(planId) || planId <= 0 || !details.trim()) {
    return sendJson(res, 400, { error: "Production Capacity not Planned " });
  }
  const lines = details.split("\r");
  for (const line of lines) {
    const cells = line.split("\t");
    const itemCode = (cells[3] || "").trim();
    const processName = (cells[6] || "").trim();
    if (itemCode) {
      const item = await pool.query(
        `SELECT item_id FROM item
         WHERE factory_id = $1 AND year_label = $2 AND item_code = $3`,
        [factory, year, itemCode]
      );
      if (item.rowCount === 0) return sendJson(res, 400, { error: "Item Does not exist" });
    }
    if (processName) {
      const proc = await pool.query(
        `SELECT proc_id FROM process_id
         WHERE factory_id = $1 AND year_label = $2 AND proc_name = $3`,
        [factory, year, processName]
      );
      if (proc.rowCount === 0) return sendJson(res, 400, { error: "Process Does not exist" });
    }
  }
  await pool.query(
    `INSERT INTO plan_prod_capa (factory_id, year_label, plan_id, flex_rows, details)
     VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (factory_id, year_label, plan_id)
     DO UPDATE SET flex_rows = EXCLUDED.flex_rows, details = EXCLUDED.details`,
    [factory, year, planId, Number.isInteger(flexRows) ? flexRows : lines.length + 2, details]
  );
  sendJson(res, 200, { ok: true });
}

