async function handleSchdGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const factory = session.factory_id;
  const year = session.year_label;
  const url = new URL(req.url, "http://127.0.0.1");
  const schYear = Number(url.searchParams.get("year") || 0);
  const schMonth = Number(url.searchParams.get("month") || 0);
  const asked = Number(url.searchParams.get("schId") || 0);
  const items = await pool.query(
    `SELECT item_code FROM item
     WHERE factory_id = $1 AND year_label = $2 AND COALESCE(hide, false) = false
     ORDER BY item_code`,
    [factory, year]
  );
  const ids = await pool.query(
    `SELECT sch_id FROM prod_schd
     WHERE factory_id = $1 AND year_label = $2 AND sch_year = $3 AND sch_month = $4
     ORDER BY sch_id`,
    [factory, year, schYear, schMonth]
  );
  const max = await pool.query(
    `SELECT COALESCE(MAX(sch_id), 0) AS n FROM prod_schd
     WHERE factory_id = $1 AND year_label = $2`,
    [factory, year]
  );
  let plan = null;
  const schId = asked || (ids.rows.length ? Number(ids.rows[ids.rows.length - 1].sch_id) : 0);
  if (schId) {
    const header = await pool.query(
      `SELECT sch_id, sch_year, sch_month FROM prod_schd
       WHERE factory_id = $1 AND year_label = $2 AND sch_id = $3`,
      [factory, year, schId]
    );
    if (header.rowCount) {
      const lines = await pool.query(
        `SELECT s.sl_no, i.item_code, s.target_qty, s.day_qty
         FROM prod_schd_sub s
         LEFT JOIN item i ON i.factory_id = s.factory_id AND i.year_label = s.year_label AND i.item_id = s.item_id
         WHERE s.factory_id = $1 AND s.year_label = $2 AND s.sch_id = $3
         ORDER BY s.sl_no`,
        [factory, year, schId]
      );
      plan = {
        schId: Number(header.rows[0].sch_id),
        year: Number(header.rows[0].sch_year),
        month: Number(header.rows[0].sch_month),
        lines: lines.rows.map((row) => ({
          slno: Number(row.sl_no),
          code: row.item_code || "",
          target: row.target_qty == null ? "" : String(row.target_qty),
          days: Array.isArray(row.day_qty) ? row.day_qty.map((value) => value == null ? "" : String(value)) : []
        }))
      };
    }
  }
  sendJson(res, 200, {
    items: items.rows.map((row) => row.item_code),
    ids: ids.rows.map((row) => Number(row.sch_id)),
    nextId: Number(max.rows[0].n) + 1,
    plan
  });
}

async function handleSchdSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const body = await readBody(req);
  const factory = session.factory_id;
  const year = session.year_label;
  const schId = Number(body.schId);
  const schYear = Number(body.year);
  const schMonth = Number(body.month);
  const lines = Array.isArray(body.lines) ? body.lines : [];
  if (!Number.isInteger(schId) || schId <= 0 || !lines.length) {
    return sendJson(res, 400, { error: "Please Enter the ItemName/Item details by clicking the grid heading..." });
  }
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO prod_schd (factory_id, year_label, sch_id, sch_year, sch_month)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (factory_id, year_label, sch_id)
       DO UPDATE SET sch_year = EXCLUDED.sch_year, sch_month = EXCLUDED.sch_month`,
      [factory, year, schId, schYear, schMonth]
    );
    await client.query(
      `DELETE FROM prod_schd_sub WHERE factory_id = $1 AND year_label = $2 AND sch_id = $3`,
      [factory, year, schId]
    );
    let slno = 0;
    for (const line of lines) {
      slno += 1;
      const item = await client.query(
        `SELECT item_id FROM item
         WHERE factory_id = $1 AND year_label = $2 AND item_code = $3`,
        [factory, year, String(line.code || "").trim()]
      );
      if (item.rowCount === 0) {
        await client.query("ROLLBACK");
        return sendJson(res, 400, { error: "Part No. does not exist ... Press F5 Key to Add New Items!!!" });
      }
      const days = Array.isArray(line.days) ? line.days.map((value) => {
        const number = Number(value);
        return Number.isFinite(number) ? number : 0;
      }) : [];
      await client.query(
        `INSERT INTO prod_schd_sub
           (factory_id, year_label, sch_id, sl_no, item_id, target_qty, day_qty)
         VALUES ($1, $2, $3, $4, $5, $6, $7)`,
        [factory, year, schId, slno, item.rows[0].item_id, Number(line.target) || 0, days]
      );
    }
    await client.query("COMMIT");
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  } finally {
    client.release();
  }
  sendJson(res, 200, { ok: true });
}

