// -------------------------------------------------------------
// SALES / LABOUR - DC Inwards (frmDCIncoming)
// -------------------------------------------------------------
async function labourDcInBundle(session, targetDcId, targetDcNo) {
  const customers = await pool.query(
    `SELECT cust_id, cust_name, contact, cust_addr FROM customer
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY cust_name`,
    [session.factory_id, session.year_label]
  );

  const stores = await pool.query(
    `SELECT store_id, store_name FROM store
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY store_name`,
    [session.factory_id, session.year_label]
  );

  const costCenters = await pool.query(
    `SELECT id, cost_cntr FROM cost_center
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY cost_cntr`,
    [session.factory_id, session.year_label]
  );

  const items = await pool.query(
    `SELECT item_id, item_code, item_name, measure_unit, rate FROM item
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY item_code`,
    [session.factory_id, session.year_label]
  );

  const nextQ = await pool.query(
    `SELECT COALESCE(MAX(dcid), 0) + 1 AS next_id FROM dcincoming
     WHERE factory_id = $1 AND year_label = $2`,
    [session.factory_id, session.year_label]
  );
  const nextId = Number(nextQ.rows[0]?.next_id || 1);

  const allIdsQ = await pool.query(
    `SELECT dcid FROM dcincoming
     WHERE factory_id = $1 AND year_label = $2
     ORDER BY dcid ASC`,
    [session.factory_id, session.year_label]
  );
  const ids = allIdsQ.rows.map((r) => Number(r.dcid));

  let dcRecord = null;
  let lines = [];
  let isLocked = false;

  let activeId = Number(targetDcId || 0);
  if (!activeId && targetDcNo) {
    const fQ = await pool.query(
      `SELECT dcid FROM dcincoming
       WHERE factory_id = $1 AND year_label = $2 AND LOWER(TRIM(dcno)) = LOWER(TRIM($3))
       LIMIT 1`,
      [session.factory_id, session.year_label, targetDcNo]
    );
    if (fQ.rowCount > 0) activeId = Number(fQ.rows[0].dcid);
  }

  if (activeId > 0) {
    const headerQ = await pool.query(
      `SELECT d.*, c.cust_name, s.store_name, cc.cost_cntr
       FROM dcincoming d
       LEFT JOIN customer c ON c.cust_id = d.custid AND c.factory_id = d.factory_id AND c.year_label = d.year_label
       LEFT JOIN store s ON s.store_id = d.storeid AND s.factory_id = d.factory_id AND s.year_label = d.year_label
       LEFT JOIN cost_center cc ON cc.id = d.costcntrid AND cc.factory_id = d.factory_id AND cc.year_label = d.year_label
       WHERE d.factory_id = $1 AND d.year_label = $2 AND d.dcid = $3
       LIMIT 1`,
      [session.factory_id, session.year_label, activeId]
    );
    if (headerQ.rowCount > 0) {
      dcRecord = headerQ.rows[0];

      const subQ = await pool.query(
        `SELECT sub.*, 
                i_in.item_code AS code_in, i_in.item_name AS name_in, i_in.measure_unit AS uom_in,
                i_out.item_code AS code_out, i_out.item_name AS name_out, i_out.measure_unit AS uom_out
         FROM dcincomingsub sub
         LEFT JOIN item i_in ON i_in.item_id = sub.itemidin AND i_in.factory_id = sub.factory_id AND i_in.year_label = sub.year_label
         LEFT JOIN item i_out ON i_out.item_id = sub.itemid AND i_out.factory_id = sub.factory_id AND i_out.year_label = sub.year_label
         WHERE sub.factory_id = $1 AND sub.year_label = $2 AND sub.dcid = $3
         ORDER BY sub.slno ASC`,
        [session.factory_id, session.year_label, activeId]
      );

      // Check if downstream outgoing DC consumed quantity
      const lockedQ = await pool.query(
        `SELECT 1 FROM dcincomingsub
         WHERE factory_id = $1 AND year_label = $2 AND dcid = $3 AND qty <> balqty AND qty > 0
         LIMIT 1`,
        [session.factory_id, session.year_label, activeId]
      );
      if (lockedQ.rowCount > 0) isLocked = true;

      // Group consolidated lines by integer part of slno
      const lineMap = new Map();
      for (const r of subQ.rows) {
        const rowSlNo = Number(r.slno);
        const groupIndex = Math.floor(rowSlNo);
        if (!lineMap.has(groupIndex)) {
          lineMap.set(groupIndex, {
            slno: groupIndex,
            itemidin: 0,
            itemcode_in: "",
            itemname_in: "",
            uom_in: "",
            qtyin: 0,
            itemid: 0,
            itemcode_out: "",
            itemname_out: "",
            uom_out: "",
            qty: 0,
            balqty: 0,
            dcrowrem: r.dcrowrem || ""
          });
        }
        const grp = lineMap.get(groupIndex);
        if (Math.abs(rowSlNo - groupIndex) < 0.005) {
          // Integer row: IN item
          grp.itemidin = Number(r.itemidin || 0);
          grp.itemcode_in = r.code_in || r.code || "";
          grp.itemname_in = r.name_in || r.name || "";
          grp.uom_in = r.uom_in || "";
          grp.qtyin = Number(r.qtyin || 0);
          if (r.dcrowrem) grp.dcrowrem = r.dcrowrem;
        } else {
          // Decimal row: OUT item
          grp.itemid = Number(r.itemid || 0);
          grp.itemcode_out = r.code_out || r.code || "";
          grp.itemname_out = r.name_out || r.name || "";
          grp.uom_out = r.uom_out || "";
          grp.qty = Number(r.qty || 0);
          grp.balqty = Number(r.balqty || 0);
          if (r.dcrowrem) grp.dcrowrem = r.dcrowrem;
        }
      }
      lines = Array.from(lineMap.values()).sort((a, b) => a.slno - b.slno);
    }
  }

  let firstId = null, prevId = null, nextRecId = null, lastId = null;
  if (ids.length > 0) {
    firstId = ids[0];
    lastId = ids[ids.length - 1];
    if (activeId > 0) {
      const idx = ids.indexOf(activeId);
      if (idx > 0) prevId = ids[idx - 1];
      if (idx >= 0 && idx < ids.length - 1) nextRecId = ids[idx + 1];
    }
  }

  return {
    customers: customers.rows,
    stores: stores.rows,
    costCenters: costCenters.rows,
    items: items.rows,
    nextId,
    activeId,
    dcRecord,
    lines,
    isLocked,
    nav: {
      firstId,
      prevId,
      nextId: nextRecId,
      lastId,
      totalCount: ids.length
    }
  };
}

async function handleLabourDcInGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  if (url.searchParams.get("new") === "1") {
    return sendJson(res, 200, await labourDcInBundle(session, 0));
  }

  const idParam = Number(url.searchParams.get("id") || 0);
  const dcNoParam = String(url.searchParams.get("dcNo") || "").trim();

  let targetId = idParam;
  if (!targetId && dcNoParam) {
    const findQ = await pool.query(
      `SELECT dcid FROM dcincoming
       WHERE factory_id = $1 AND year_label = $2 AND LOWER(TRIM(dcno)) = LOWER(TRIM($3))
       LIMIT 1`,
      [session.factory_id, session.year_label, dcNoParam]
    );
    if (findQ.rowCount > 0) targetId = Number(findQ.rows[0].dcid);
  }

  if (!targetId) {
    const lastQ = await pool.query(
      `SELECT dcid FROM dcincoming
       WHERE factory_id = $1 AND year_label = $2
       ORDER BY dcid DESC LIMIT 1`,
      [session.factory_id, session.year_label]
    );
    if (lastQ.rowCount > 0) targetId = Number(lastQ.rows[0].dcid);
  }

  const data = await labourDcInBundle(session, targetId);
  return sendJson(res, 200, data);
}

