async function handleMatReqGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const factory = session.factory_id;
  const year = session.year_label;
  const assemblies = await pool.query(
    `SELECT i.item_id, i.item_code
     FROM item i
     WHERE i.factory_id = $1 AND i.year_label = $2
       AND i.item_id IN (
         SELECT DISTINCT d.assmbly_id FROM assmbly_def d
         WHERE d.factory_id = i.factory_id AND d.year_label = i.year_label
           AND COALESCE(d.is_obsolete, false) = false
       )
     ORDER BY i.item_code`,
    [factory, year]
  );
  const parts = await pool.query(
    `SELECT p.item_id, p.item_code, p.category_code, p.measure_unit,
            EXISTS (
              SELECT 1 FROM category c
              WHERE c.factory_id = p.factory_id AND c.year_label = p.year_label
                AND c.category_code = p.category_code AND c.category_name ILIKE '%assembly%'
            ) AS assembly_like
     FROM item p
     WHERE p.factory_id = $1 AND p.year_label = $2
       AND p.item_id IN (
         SELECT DISTINCT d.item_id FROM assmbly_def d
         WHERE d.factory_id = p.factory_id AND d.year_label = p.year_label
       )
     ORDER BY assembly_like, p.item_code`,
    [factory, year]
  );
  const utils = await pool.query(
    `SELECT DISTINCT ON (d.assmbly_id, d.item_id) d.assmbly_id, d.item_id, d.util_qty
     FROM assmbly_def d
     WHERE d.factory_id = $1 AND d.year_label = $2
     ORDER BY d.assmbly_id, d.item_id, d.sl_no DESC`,
    [factory, year]
  );
  const stock = await pool.query(
    `SELECT item_id, COALESCE(SUM(bal_qty), 0) AS on_hand
     FROM store_add_sub
     WHERE factory_id = $1 AND year_label = $2
     GROUP BY item_id`,
    [factory, year]
  );
  const stockOf = {};
  stock.rows.forEach((row) => { stockOf[String(row.item_id)] = Number(row.on_hand) || 0; });
  const utilOf = {};
  utils.rows.forEach((row) => {
    const key = String(row.item_id);
    if (!utilOf[key]) utilOf[key] = {};
    utilOf[key][String(row.assmbly_id)] = Number(row.util_qty) || 0;
  });
  const compTable = await pool.query(`SELECT to_regclass('public.comp_master') AS name`);
  const components = [];
  const rawOf = {};
  if (compTable.rows[0].name) {
    const componentRows = await pool.query(
      `SELECT i.item_id, i.item_code
       FROM item i
       WHERE i.factory_id = $1 AND i.year_label = $2 AND i.category_code = 2
         AND i.item_id IN (
           SELECT c.item_id FROM comp_master c
           WHERE c.factory_id = i.factory_id AND c.year_label = i.year_label
         )
       ORDER BY i.item_code`,
      [factory, year]
    );
    componentRows.rows.forEach((row) => components.push({ id: row.item_id, code: row.item_code || "" }));
    const rawRows = await pool.query(
      `SELECT c.item_id, c.rm_id, c.weight, r.item_code AS rm_code, r.measure_unit AS rm_unit
       FROM comp_master c
       LEFT JOIN item r ON r.factory_id = c.factory_id AND r.year_label = c.year_label
         AND r.item_id = c.rm_id AND r.category_code = 1
       WHERE c.factory_id = $1 AND c.year_label = $2`,
      [factory, year]
    );
    rawRows.rows.forEach((row) => {
      rawOf[String(row.item_id)] = {
        code: row.rm_code || "",
        unit: row.rm_unit || "",
        weight: row.weight === null || row.weight === undefined ? null : Number(row.weight)
      };
    });
  }
  return sendJson(res, 200, {
    assemblies: assemblies.rows.map((row) => ({ id: row.item_id, code: row.item_code || "", po: 0 })),
    parts: parts.rows.map((row) => {
      const raw = rawOf[String(row.item_id)] || {};
      return {
        id: row.item_id,
        code: row.item_code || "",
        category: Number(row.category_code) || 0,
        assemblyLike: row.assembly_like === true,
        stock: stockOf[String(row.item_id)] || 0,
        utils: utilOf[String(row.item_id)] || {},
        rmCode: raw.code || "",
        rmUnit: raw.unit || "",
        weight: raw.weight === undefined ? null : raw.weight
      };
    }),
    components
  });
}

async function handleAssmReqGet(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });
  const assemblies = await pool.query(
    `SELECT i.item_id, i.item_code, i.item_name
     FROM item i
     WHERE i.factory_id = $1 AND i.year_label = $2
       AND i.category_code = 3
       AND COALESCE(i.hide, false) = false
       AND EXISTS (
         SELECT 1 FROM assmbly_def d
         WHERE d.factory_id = i.factory_id AND d.year_label = i.year_label AND d.assmbly_id = i.item_id
       )
     ORDER BY i.item_code`,
    [session.factory_id, session.year_label]
  );
  const lines = await pool.query(
    `SELECT d.assmbly_id, d.sl_no, d.util_qty, p.item_code, p.measure_unit,
            COALESCE(SUM(s.bal_qty), 0) AS on_hand,
            EXISTS (
              SELECT 1 FROM category c
              WHERE c.factory_id = p.factory_id AND c.year_label = p.year_label
                AND c.category_code = p.category_code AND c.category_name ILIKE '%ASSEMBLY%'
            ) AS is_assembly
     FROM assmbly_def d
     JOIN item p ON p.factory_id = d.factory_id AND p.year_label = d.year_label AND p.item_id = d.item_id
     LEFT JOIN store_add_sub s ON s.factory_id = d.factory_id AND s.year_label = d.year_label AND s.item_id = d.item_id
     WHERE d.factory_id = $1 AND d.year_label = $2
     GROUP BY d.assmbly_id, d.sl_no, d.util_qty, p.item_code, p.measure_unit, p.factory_id, p.year_label, p.category_code
     ORDER BY d.assmbly_id, d.sl_no`,
    [session.factory_id, session.year_label]
  );
  const byAssembly = {};
  lines.rows.forEach((row) => {
    const key = String(row.assmbly_id);
    if (!byAssembly[key]) byAssembly[key] = [];
    byAssembly[key].push({
      slno: row.sl_no,
      code: row.item_code || "",
      util: Number(row.util_qty) || 0,
      onHand: Number(row.on_hand) || 0,
      uom: row.measure_unit || "",
      assembly: row.is_assembly === true
    });
  });
  return sendJson(res, 200, {
    assemblies: assemblies.rows.map((row) => ({
      id: row.item_id,
      code: row.item_code || "",
      name: row.item_name || "",
      lines: byAssembly[String(row.item_id)] || []
    }))
  });
}

async function handleAttendanceGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const curDate = new Date();
  const year = Number(url.searchParams.get("year")) || curDate.getFullYear();
  const monthId = Number(url.searchParams.get("monthId")) || (curDate.getMonth() + 1);

  const daysInMonth = new Date(year, monthId, 0).getDate();

  const monthListRes = await pool.query("SELECT monthid, monthname FROM month1 ORDER BY monthid");
  const monthRow = monthListRes.rows.find((m) => Number(m.monthid) === monthId);
  const monthName = monthRow ? monthRow.monthname : "";

  const startDate = `${year}-${String(monthId).padStart(2, "0")}-01`;
  const endDate = `${year}-${String(monthId).padStart(2, "0")}-${String(daysInMonth).padStart(2, "0")}`;

  const staffRes = await pool.query(
    `SELECT staff_id, staff_name, doj, dol
     FROM staff
     WHERE factory_id = $1
       AND doj <= $2
       AND (dol >= $3 OR dol IS NULL)
     ORDER BY staff_id`,
    [session.factory_id, endDate, startDate]
  );

  const holRes = await pool.query(
    `SELECT holidays FROM holidays
     WHERE factory_id = $1 AND year = $2 AND monthid = $3
     LIMIT 1`,
    [session.factory_id, year, monthId]
  );

  let holidaysStr = "";
  if (holRes.rowCount > 0 && holRes.rows[0].holidays) {
    holidaysStr = holRes.rows[0].holidays;
  }
  if (holidaysStr.length < daysInMonth) {
    holidaysStr = holidaysStr.padEnd(daysInMonth, "0");
  } else if (holidaysStr.length > daysInMonth) {
    holidaysStr = holidaysStr.slice(0, daysInMonth);
  }

  const attRes = await pool.query(
    `SELECT staffid, ldetail, otdetail
     FROM attendance
     WHERE factory_id = $1 AND year = $2 AND monthid = $3`,
    [session.factory_id, year, monthId]
  );
  const attMap = new Map();
  for (const r of attRes.rows) {
    attMap.set(Number(r.staffid), r);
  }

  const staffData = staffRes.rows.map((st, idx) => {
    const existing = attMap.get(Number(st.staff_id));
    let ldetail = existing ? existing.ldetail : "";
    let otdetail = existing ? existing.otdetail : "";

    if (!ldetail) {
      let chars = [];
      for (let d = 0; d < daysInMonth; d++) {
        chars.push(holidaysStr[d] === "1" ? "H" : " ");
      }
      ldetail = chars.join("");
    } else {
      if (ldetail.length < daysInMonth) {
        ldetail = ldetail.padEnd(daysInMonth, " ");
      } else if (ldetail.length > daysInMonth) {
        ldetail = ldetail.slice(0, daysInMonth);
      }
    }

    if (!otdetail) {
      otdetail = new Array(daysInMonth).fill("0").join(",");
    }

    return {
      sl: idx + 1,
      staffId: st.staff_id,
      staffName: st.staff_name,
      ldetail,
      otdetail
    };
  });

  return sendJson(res, 200, {
    year,
    monthId,
    monthName,
    daysInMonth,
    months: monthListRes.rows,
    holidays: holidaysStr,
    staff: staffData
  });
}

// --- Maintenance Schedule & Process Handlers ---
async function handleMaintainScheduleGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  // Get types list
  let typesQ = await pool.query(
    "SELECT mainid, mainname FROM maintenance WHERE factory_id = $1 ORDER BY mainid",
    [session.factory_id]
  );
  if (typesQ.rowCount === 0) {
    typesQ = await pool.query("SELECT mainid, mainname FROM maintenance ORDER BY mainid");
  }

  // Get machines list
  let machQ = await pool.query(
    "SELECT mach_id, mach_name FROM machine WHERE factory_id = $1 ORDER BY mach_id",
    [session.factory_id]
  );
  if (machQ.rowCount === 0) {
    machQ = await pool.query("SELECT mach_id, mach_name FROM machine ORDER BY mach_id");
  }

  const mainIdParam = url.searchParams.get("mainId");
  const selectedMainId = mainIdParam ? Number(mainIdParam) : (typesQ.rows[0]?.mainid || 1);

  // Get schedule rows for selected mainId
  const schQ = await pool.query(
    `SELECT m.mach_id, m.mach_name, COALESCE(s.descr, '') AS descr, COALESCE(s.schday, 1) AS schday
     FROM machine m
     LEFT JOIN maintainsch s ON s.machid = m.mach_id AND s.mainid = $1 AND s.factory_id = $2
     WHERE m.factory_id = $2 OR m.factory_id IS NULL
     ORDER BY m.mach_id`,
    [selectedMainId, session.factory_id]
  );

  return sendJson(res, 200, {
    types: typesQ.rows,
    selectedMainId,
    machines: machQ.rows,
    schedule: schQ.rows
  });
}

async function handleMaintainScheduleSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const body = await readBody(req);
  const mainId = Number(body.mainId);
  const rows = Array.isArray(body.rows) ? body.rows : [];

  if (!mainId) {
    return sendJson(res, 400, { error: "Select a Maintenance Type ..." });
  }

  // Validate limits per frequency
  for (const r of rows) {
    const day = Number(r.schday || 1);
    if (mainId === 1 && (day < 1 || day > 7)) {
      return sendJson(res, 400, { error: "Scheduled Day must be between 1 and 7 (1-Sunday 7-Saturday)" });
    }
    if (mainId === 2 && (day < 1 || day > 13)) {
      return sendJson(res, 400, { error: "Scheduled Day must be between 1 and 13" });
    }
    if (mainId === 3 && (day < 1 || day > 28)) {
      return sendJson(res, 400, { error: "Scheduled Day must be between 1 and 28" });
    }
    if (mainId === 4 && (day < 1 || day > 3)) {
      return sendJson(res, 400, { error: "Scheduled Month must be between 1 and 3 (1-January 3-March)" });
    }
    if (mainId === 5 && (day < 1 || day > 6)) {
      return sendJson(res, 400, { error: "Scheduled Month must be between 1 and 6 (1-January 6-June)" });
    }
    if (mainId === 6 && (day < 1 || day > 12)) {
      return sendJson(res, 400, { error: "Scheduled Month must be between 1 and 12 (1-January 12-December)" });
    }
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    for (const r of rows) {
      const machId = Number(r.mach_id || r.machid);
      const descr = String(r.descr || "").trim();
      const schday = Number(r.schday || 1);

      await client.query(
        `INSERT INTO maintainsch (factory_id, year_label, mainid, machid, descr, schday)
         VALUES ($1, $2, $3, $4, $5, $6)
         ON CONFLICT (factory_id, year_label, mainid, machid)
         DO UPDATE SET descr = EXCLUDED.descr, schday = EXCLUDED.schday`,
        [session.factory_id, session.year_label, mainId, machId, descr, schday]
      );
    }
    await client.query("COMMIT");
    return sendJson(res, 200, { success: true, message: "Data stored successfully ." });
  } catch (err) {
    await client.query("ROLLBACK");
    console.error("handleMaintainScheduleSave error:", err);
    return sendJson(res, 500, { error: err.message });
  } finally {
    client.release();
  }
}

async function handleMaintainProcessGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const dateParam = url.searchParams.get("date") || new Date().toISOString().slice(0, 10);

  // Get all machines
  let machQ = await pool.query(
    "SELECT mach_id, mach_name FROM machine WHERE factory_id = $1 ORDER BY mach_id",
    [session.factory_id]
  );
  if (machQ.rowCount === 0) {
    machQ = await pool.query("SELECT mach_id, mach_name FROM machine ORDER BY mach_id");
  }

  if (machQ.rowCount === 0) {
    return sendJson(res, 400, { error: "No Machine exists!!!" });
  }

  // Get schedule details for all machines and M1..M6
  const schQ = await pool.query(
    "SELECT mainid, machid, descr FROM maintainsch WHERE factory_id = $1",
    [session.factory_id]
  );
  const schMap = {};
  schQ.rows.forEach(r => {
    schMap[`${r.machid}_${r.mainid}`] = r.descr;
  });

  // Get process entries for this date
  const dataQ = await pool.query(
    "SELECT mainid, machid, statusc FROM maintaindata WHERE factory_id = $1 AND maindate = $2",
    [session.factory_id, dateParam]
  );
  const dataMap = {};
  dataQ.rows.forEach(r => {
    dataMap[`${r.machid}_${r.mainid}`] = r.statusc;
  });

  const matrix = machQ.rows.map(m => {
    const row = {
      mach_id: m.mach_id,
      mach_name: m.mach_name
    };
    for (let mainId = 1; mainId <= 6; mainId++) {
      row[`m${mainId}_descr`] = schMap[`${m.mach_id}_${mainId}`] || "";
      row[`m${mainId}_status`] = dataMap[`${m.mach_id}_${mainId}`] || false;
    }
    return row;
  });

  return sendJson(res, 200, {
    date: dateParam,
    matrix
  });
}

async function handleMaintainProcessSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const body = await readBody(req);
  const dateStr = body.date || new Date().toISOString().slice(0, 10);
  const matrix = Array.isArray(body.matrix) ? body.matrix : [];

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    for (const row of matrix) {
      const machId = Number(row.mach_id);
      for (let mainId = 1; mainId <= 6; mainId++) {
        const statusc = !!row[`m${mainId}_status`];
        const descr = String(row[`m${mainId}_descr`] || "");

        await client.query(
          `INSERT INTO maintaindata (factory_id, year_label, mainid, machid, maindate, statusc, descr)
           VALUES ($1, $2, $3, $4, $5, $6, $7)
           ON CONFLICT (factory_id, year_label, mainid, machid, maindate)
           DO UPDATE SET statusc = EXCLUDED.statusc, descr = EXCLUDED.descr`,
          [session.factory_id, session.year_label, mainId, machId, dateStr, statusc, descr]
        );
      }
    }
    await client.query("COMMIT");
    return sendJson(res, 200, { success: true, message: "Data stored successfully ." });
  } catch (err) {
    await client.query("ROLLBACK");
    console.error("handleMaintainProcessSave error:", err);
    return sendJson(res, 500, { error: err.message });
  } finally {
    client.release();
  }
}

// --- Breakdown Maintenance Handlers ---
async function handleBreakdownGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const fromDate = url.searchParams.get("from");
  const toDate = url.searchParams.get("to");

  let query = `
    SELECT b.id, TO_CHAR(b.brkdate, 'YYYY-MM-DD') AS brkdate, TO_CHAR(b.brkdate, 'DD/MM/YYYY') AS brkdate_disp,
           b.machid, m.mach_name, b.brkfrom, b.brkdet, b.brkto, b.detcorrect, b.amt, b.timespent
    FROM brkdown b
    JOIN machine m ON m.mach_id = b.machid
    WHERE b.factory_id = $1
  `;
  const params = [session.factory_id];
  if (fromDate && toDate) {
    params.push(fromDate, toDate);
    query += ` AND b.brkdate BETWEEN $2 AND $3`;
  }
  query += ` ORDER BY b.id DESC`;

  const rowsQ = await pool.query(query, params);

  // Also get machines for dropdown
  let machQ = await pool.query("SELECT mach_id, mach_name FROM machine WHERE factory_id = $1 ORDER BY mach_name", [session.factory_id]);
  if (machQ.rowCount === 0) {
    machQ = await pool.query("SELECT mach_id, mach_name FROM machine ORDER BY mach_name");
  }

  return sendJson(res, 200, {
    records: rowsQ.rows,
    machines: machQ.rows
  });
}

