// --- Calibration Handlers ---
async function handleCalibrateGet(req, res, url) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const calIdParam = url.searchParams.get("id");
  const dueOnly = url.searchParams.get("due") === "true";

  let query = `
    SELECT id, itemid, insgaugeid, freq, range, lc,
           TO_CHAR(nextcalibrate, 'YYYY-MM-DD') AS nextcalibrate,
           TO_CHAR(nextcalibrate, 'DD/MM/YYYY') AS nextcalibrate_disp,
           otherdet
    FROM calibrate
    WHERE factory_id = $1
  `;
  const params = [session.factory_id];
  if (dueOnly) {
    query += ` AND nextcalibrate <= CURRENT_DATE + INTERVAL '30 days'`;
  }
  query += ` ORDER BY id DESC`;

  const calQ = await pool.query(query, params);

  let selectedCal = null;
  let reports = [];

  if (calIdParam) {
    const calId = Number(calIdParam);
    const selQ = await pool.query("SELECT * FROM calibrate WHERE id = $1 AND factory_id = $2 LIMIT 1", [calId, session.factory_id]);
    if (selQ.rowCount > 0) selectedCal = selQ.rows[0];

    const repQ = await pool.query(
      `SELECT calibrepid, id, TO_CHAR(docalibrate, 'YYYY-MM-DD') AS docalibrate,
              TO_CHAR(docalibrate, 'DD/MM/YYYY') AS docalibrate_disp,
              calibrateno, calibratestat, calibratedet, authorised
       FROM calibraterep
       WHERE id = $1 AND factory_id = $2
       ORDER BY calibrepid DESC`,
      [calId, session.factory_id]
    );
    reports = repQ.rows;
  }

  return sendJson(res, 200, {
    instruments: calQ.rows,
    selected: selectedCal,
    reports
  });
}

