async function handleCalibrateReportSave(req, res) {
  const session = await openSession(req);
  if (!session) return sendJson(res, 401, { error: "Sign in first." });

  const body = await readBody(req);
  const id = Number(body.id);
  const doCal = body.docalibrate || new Date().toISOString().slice(0, 10);
  const calNo = String(body.calibrateno || "").trim();
  const calStat = String(body.calibratestat || "Accepted").trim();
  const calDet = String(body.calibratedet || "").trim();
  const auth = String(body.authorised || "").trim();

  if (!id) return sendJson(res, 400, { error: "Instrument ID required." });

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query(
      `INSERT INTO calibraterep (id, factory_id, year_label, docalibrate, calibrateno, calibratestat, calibratedet, authorised)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
      [id, session.factory_id, session.year_label, doCal, calNo, calStat, calDet, auth]
    );

    // Compute next calibration date based on instrument frequency
    const calQ = await client.query("SELECT freq FROM calibrate WHERE id = $1 LIMIT 1", [id]);
    const freqMonths = Number(calQ.rows[0]?.freq || 12);
    const d = new Date(doCal);
    d.setMonth(d.getMonth() + freqMonths);
    const nextDate = d.toISOString().slice(0, 10);

    await client.query("UPDATE calibrate SET nextcalibrate = $1 WHERE id = $2", [nextDate, id]);

    await client.query("COMMIT");
    return sendJson(res, 200, { success: true, message: "Records Updated ." });
  } catch (err) {
    await client.query("ROLLBACK");
    console.error("handleCalibrateReportSave error:", err);
    return sendJson(res, 500, { error: err.message });
  } finally {
    client.release();
  }
}

