      await client.query(
        `INSERT INTO attendance (factory_id, year_label, year, monthid, staffid, ldetail, otdetail, updated_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, CURRENT_TIMESTAMP)
         ON CONFLICT (factory_id, year_label, year, monthid, staffid)
         DO UPDATE SET ldetail = EXCLUDED.ldetail, otdetail = EXCLUDED.otdetail, updated_at = CURRENT_TIMESTAMP`,
        [session.factory_id, session.year_label, year, monthId, staffId, ldetail, otdetail]
      );
